-- afterhours — "who is this?" for 16 more nights in Munich (12.10.2026)
--
-- A one-shot for the LIVE project, after 40_event_about.sql and about-munich.sql.
-- The texts were written from the Wikipedia summary of each act (English or German,
-- nothing added from elsewhere) and read against it once more. Eighteen of the
-- upcoming Munich nights have no page or land on the wrong one (Yung Pepp, THIZZY52,
-- Kristina Bogansky, Jamie Grey, Neunundneunzig, Darren Kiely, Jero19, HULLIS, King
-- No-One, heylucas, Ulle und Rick, Gurriers, re6ce, Empire of Giants, moe, WesGhost,
-- JOHNO37, the Old but Gold party) and were left out. Nights are found by slug; a
-- night that is gone is skipped; a row that exists is replaced.
--
-- In the Supabase panel: SQL Editor → New query → paste → Run.

insert into public.event_about (event_id, lang, name, kicker, who, facts, source_url)
select e.id, v.lang, v.name, v.kicker, v.who, v.facts, v.source_url
from (values
  ('eve-scorpion-tour-f8161d04', 'tr', 'Eve', 'rapçi, şarkıcı ve oyuncu · abd', 'Amerikalı rapçi, şarkıcı ve oyuncu. İlk albümü Let There Be Eve... Ruff Ryders'' First Lady (1999) ABD listesinde bir numaraya çıktı; bunu başaran üçüncü kadın rapçi oldu.', array['Gwen Stefani ile "Let Me Blow Ya Mind", en iyi rap/şarkı iş birliği dalındaki ilk Grammy''yi kazandı.', 'Turneye adını veren Scorpion albümü 2001''de çıktı.']::text[], 'https://en.wikipedia.org/wiki/Eve_(rapper)'),
  ('eve-scorpion-tour-f8161d04', 'en', 'Eve', 'rapper, singer and actress · usa', 'An American rapper, singer and actress. Her first album, Let There Be Eve... Ruff Ryders'' First Lady (1999), went to number one in the US; she was the third female rapper to do that.', array['"Let Me Blow Ya Mind" with Gwen Stefani won the first ever Grammy for best rap/sung collaboration.', 'Scorpion, the album this tour is named after, came out in 2001.']::text[], 'https://en.wikipedia.org/wiki/Eve_(rapper)'),
  ('eve-scorpion-tour-f8161d04', 'de', 'Eve', 'rapperin, sängerin und schauspielerin · usa', 'US-amerikanische Rapperin, Sängerin und Schauspielerin. Ihr erstes Album Let There Be Eve... Ruff Ryders'' First Lady (1999) stieg in den USA auf Platz eins; sie war die dritte Rapperin, der das gelang.', array['„Let Me Blow Ya Mind“ mit Gwen Stefani gewann den allerersten Grammy für die beste Rap/Gesang-Kollaboration.', 'Scorpion, das Album, nach dem diese Tour heißt, erschien 2001.']::text[], 'https://en.wikipedia.org/wiki/Eve_(rapper)'),
  ('simple-plan-bigger-than-you-think-europe-tour-20-b7d0f727', 'tr', 'Simple Plan', 'rock grubu · 1999, montréal', 'Montréal''den rock grubu, 1999''dan beri aynı dörtlü: Pierre Bouvier, Chuck Comeau, Jeff Stinco ve Sébastien Lefebvre. Altı stüdyo albümü var; ilki No Pads, No Helmets... Just Balls (2002), sonuncusu Harder Than It Looks (2022).', array['2010 Vancouver Kış Olimpiyatları''nın kapanış töreninde çaldılar.', 'What''s New, Scooby-Doo? dizisinin açılış şarkısı onların.']::text[], 'https://en.wikipedia.org/wiki/Simple_Plan'),
  ('simple-plan-bigger-than-you-think-europe-tour-20-b7d0f727', 'en', 'Simple Plan', 'rock band · 1999, montreal', 'A rock band from Montreal, together since 1999 with the same four: Pierre Bouvier, Chuck Comeau, Jeff Stinco and Sébastien Lefebvre. Six studio albums, from No Pads, No Helmets... Just Balls (2002) to Harder Than It Looks (2022).', array['They played the closing ceremony of the 2010 Winter Olympics in Vancouver.', 'They wrote and sang the theme of What''s New, Scooby-Doo?']::text[], 'https://en.wikipedia.org/wiki/Simple_Plan'),
  ('simple-plan-bigger-than-you-think-europe-tour-20-b7d0f727', 'de', 'Simple Plan', 'rockband · 1999, montréal', 'Rockband aus Montréal, seit 1999 in derselben Besetzung: Pierre Bouvier, Chuck Comeau, Jeff Stinco und Sébastien Lefebvre. Sechs Studioalben, von No Pads, No Helmets... Just Balls (2002) bis Harder Than It Looks (2022).', array['Sie spielten bei der Abschlussfeier der Olympischen Winterspiele 2010 in Vancouver.', 'Das Titellied von What''s New, Scooby-Doo? stammt von ihnen.']::text[], 'https://de.wikipedia.org/wiki/Simple_Plan'),
  ('the-home-team-the-crucible-of-life-european-tour-1a1cc2ce', 'tr', 'The Home Team', 'rock grubu · seattle', 'Seattle''dan dört kişilik grup; 2013''te davulcu Daniel Matson ve gitarist John Baran kurdu, Brian Butcher söylüyor, Ryne Olson bas çalıyor. Üç albüm; sonuncusu The Crucible of Life (2024) turneye adını veriyor.', array['Don Broco, Senses Fail, Neck Deep ve The Used''ın önünde çaldılar.', 'The Crucible of Life, Thriller Records''tan çıktı.']::text[], 'https://en.wikipedia.org/wiki/The_Home_Team'),
  ('the-home-team-the-crucible-of-life-european-tour-1a1cc2ce', 'en', 'The Home Team', 'rock band · seattle', 'A four-piece from Seattle, started in 2013 by drummer Daniel Matson and guitarist John Baran; Brian Butcher sings, Ryne Olson plays bass. Three albums; the latest, The Crucible of Life (2024), gives this tour its name.', array['They have opened for Don Broco, Senses Fail, Neck Deep and The Used.', 'The Crucible of Life came out on Thriller Records.']::text[], 'https://en.wikipedia.org/wiki/The_Home_Team'),
  ('the-home-team-the-crucible-of-life-european-tour-1a1cc2ce', 'de', 'The Home Team', 'rockband · seattle', 'Vierköpfige Band aus Seattle, 2013 von Schlagzeuger Daniel Matson und Gitarrist John Baran gegründet; Brian Butcher singt, Ryne Olson spielt Bass. Drei Alben; das jüngste, The Crucible of Life (2024), gibt der Tour ihren Namen.', array['Sie spielten im Vorprogramm von Don Broco, Senses Fail, Neck Deep und The Used.', 'The Crucible of Life erschien bei Thriller Records.']::text[], 'https://en.wikipedia.org/wiki/The_Home_Team'),
  ('niall-horan-dinner-party-live-on-tour-e6c4bb48', 'tr', 'Niall Horan', 'şarkıcı ve söz yazarı · irlanda', 'İrlandalı şarkıcı ve söz yazarı; önce 2010''da The X Factor''da kurulan One Direction''ın üyesi olarak tanındı. 2016''dan beri solo: Flicker (2017), Heartbreak Weather (2020), The Show (2023) ve bu turnenin albümü Dinner Party (2026).', array['Flicker, İrlanda ve ABD listelerine bir numaradan girdi.', 'The Voice''ta koçluk yaptı, bir golf menajerlik şirketinin kurucularından.']::text[], 'https://en.wikipedia.org/wiki/Niall_Horan'),
  ('niall-horan-dinner-party-live-on-tour-e6c4bb48', 'en', 'Niall Horan', 'singer-songwriter · ireland', 'Irish singer and songwriter, known first as one of One Direction, the boy band formed on The X Factor in 2010. Solo since 2016: Flicker (2017), Heartbreak Weather (2020), The Show (2023) and Dinner Party (2026), the album this tour carries.', array['Flicker went to number one in Ireland and the US on its first week.', 'He has been a coach on The Voice and co-founded a golf management agency.']::text[], 'https://en.wikipedia.org/wiki/Niall_Horan'),
  ('niall-horan-dinner-party-live-on-tour-e6c4bb48', 'de', 'Niall Horan', 'singer-songwriter · irland', 'Irischer Sänger und Songwriter, zuerst bekannt als Mitglied von One Direction, der 2010 bei The X Factor gegründeten Boyband. Solo seit 2016: Flicker (2017), Heartbreak Weather (2020), The Show (2023) und Dinner Party (2026), das Album dieser Tour.', array['Flicker stieg in Irland und den USA auf Platz eins ein.', 'Er war Coach bei The Voice und hat eine Golf-Management-Agentur mitgegründet.']::text[], 'https://en.wikipedia.org/wiki/Niall_Horan'),
  ('good-charlotte-motel-du-cap-eu-uk-tour-12e606aa', 'tr', 'Good Charlotte', 'pop-punk · 1995, maryland', 'Waldorf, Maryland''den pop-punk; 1995''ten beri ikizler Joel ve Benji Madden''ın etrafında. "Lifestyles of the Rich and Famous" ve "The Anthem"ın olduğu The Young and the Hopeless (2002) yalnızca ABD''de 3,5 milyon sattı.', array['Grubun adı annelerinin ikizlere okuduğu bir çocuk kitabından geliyor.', 'Dört yıllık aradan sonra 2015''te döndüler; Generation Rx (2018) yedinci albümleri.']::text[], 'https://en.wikipedia.org/wiki/Good_Charlotte'),
  ('good-charlotte-motel-du-cap-eu-uk-tour-12e606aa', 'en', 'Good Charlotte', 'pop-punk · 1995, maryland', 'Pop-punk from Waldorf, Maryland, around the twins Joel and Benji Madden since 1995. The Young and the Hopeless (2002), with "Lifestyles of the Rich and Famous" and "The Anthem", sold 3.5 million copies in the US alone.', array['The band name comes from a children''s book their mother read to the twins.', 'After a four-year break they returned in 2015; Generation Rx (2018) is their seventh album.']::text[], 'https://en.wikipedia.org/wiki/Good_Charlotte'),
  ('good-charlotte-motel-du-cap-eu-uk-tour-12e606aa', 'de', 'Good Charlotte', 'pop-punk · 1995, maryland', 'Pop-Punk aus Waldorf, Maryland, seit 1995 um die Zwillinge Joel und Benji Madden. The Young and the Hopeless (2002), mit „Lifestyles of the Rich and Famous“ und „The Anthem“, verkaufte sich allein in den USA 3,5 Millionen Mal.', array['Der Bandname stammt aus einem Kinderbuch, das die Mutter den Zwillingen vorlas.', 'Nach vier Jahren Pause kamen sie 2015 zurück; Generation Rx (2018) ist das siebte Album.']::text[], 'https://de.wikipedia.org/wiki/Good_Charlotte'),
  ('andreas-gabalier-10-jahre-volks-rock-n-roller-un-7e0e44b8', 'tr', 'Andreas Gabalier', 'volks-rock''n''roller · avusturya', 'Avusturyalı şarkıcı, halk müziği tadında pop ve rock and roll; 1984''te Friesach''ta doğdu. En bilinen şarkıları I sing a Liad für di (2011), Amoi seg'' ma uns wieder (2014) ve Hulapalu (2015).', array['Müziğine Volks-Rock''n''Roll diyor; turne bunun on yılını unplugged kutluyor.', '21 Kasım 1984''te Friesach''ta doğdu.']::text[], 'https://de.wikipedia.org/wiki/Andreas_Gabalier'),
  ('andreas-gabalier-10-jahre-volks-rock-n-roller-un-7e0e44b8', 'en', 'Andreas Gabalier', 'volks-rock''n''roller · austria', 'Austrian singer of folk-flavoured pop and rock and roll, born in Friesach in 1984. His best known songs are I sing a Liad für di (2011), Amoi seg'' ma uns wieder (2014) and Hulapalu (2015).', array['He calls his music Volks-Rock''n''Roll; this tour marks ten years of it unplugged.', 'Born on 21 November 1984 in Friesach.']::text[], 'https://de.wikipedia.org/wiki/Andreas_Gabalier'),
  ('andreas-gabalier-10-jahre-volks-rock-n-roller-un-7e0e44b8', 'de', 'Andreas Gabalier', 'volks-rock''n''roller · österreich', 'Österreichischer Sänger der volkstümlichen Musik, 1984 in Friesach geboren. Seine bekanntesten Stücke: I sing a Liad für di (2011), Amoi seg'' ma uns wieder (2014) und Hulapalu (2015).', array['Er nennt seine Musik Volks-Rock''n''Roll; die Tour feiert zehn Jahre davon unplugged.', 'Geboren am 21. November 1984 in Friesach.']::text[], 'https://de.wikipedia.org/wiki/Andreas_Gabalier'),
  ('pa-sheehy-the-magic-we-found-tour-285ca891', 'tr', 'Pa Sheehy', 'şarkıcı ve söz yazarı · dingle, irlanda', 'County Kerry''deki Dingle''dan. İrlanda ve Avrupa listelerine giren Walking on Cars''ın solistiydi; grup 2020''de dağılınca tek başına yazmaya başladı.', array['İlk EP''si The Art of Disappearing (2021) İrlanda''da dokuzuncu oldu.', 'İlk albümü Maybe It Was All For This Ekim 2024''te çıktı.']::text[], 'https://en.wikipedia.org/wiki/Pa_Sheehy'),
  ('pa-sheehy-the-magic-we-found-tour-285ca891', 'en', 'Pa Sheehy', 'singer-songwriter · dingle, ireland', 'From Dingle in County Kerry. He sang in Walking on Cars, who had chart hits in Ireland and across Europe; since the band ended in 2020 he writes alone.', array['His first EP, The Art of Disappearing (2021), went to number nine in Ireland.', 'His first album, Maybe It Was All For This, came out in October 2024.']::text[], 'https://en.wikipedia.org/wiki/Pa_Sheehy'),
  ('pa-sheehy-the-magic-we-found-tour-285ca891', 'de', 'Pa Sheehy', 'singer-songwriter · dingle, irland', 'Aus Dingle im County Kerry. Er sang bei Walking on Cars, die in Irland und Europa Charterfolge hatten; seit dem Ende der Band 2020 schreibt er allein.', array['Seine erste EP, The Art of Disappearing (2021), erreichte Platz neun in Irland.', 'Sein erstes Album, Maybe It Was All For This, erschien im Oktober 2024.']::text[], 'https://en.wikipedia.org/wiki/Pa_Sheehy'),
  ('sace6-e8ee7fca', 'tr', 'Sace6', 'alternatif metal ikilisi · abd', 'Vokalist Sace ve gitarist Noah Thomas. Sace''in solo projesi olarak başladı, 2024''te ikili oldu: ağır gitarların üstünde yumuşak, melodik vokal ve pop nakaratlar.', array['İlk albümleri brutalist Mayıs 2026''da Sumerian Records''tan çıktı.', 'Gösterdikleri her şey bilerek siyah-beyaz.']::text[], 'https://en.wikipedia.org/wiki/Sace6'),
  ('sace6-e8ee7fca', 'en', 'Sace6', 'alternative metal duo · usa', 'Singer Sace and guitarist Noah Thomas. What began as Sace''s solo project became a duo in 2024: soft, melodic vocals and pop hooks over heavy guitars.', array['Their first album, brutalist, came out in May 2026 on Sumerian Records.', 'Everything they show is black and white, on purpose.']::text[], 'https://en.wikipedia.org/wiki/Sace6'),
  ('sace6-e8ee7fca', 'de', 'Sace6', 'alternative-metal-duo · usa', 'Sänger Sace und Gitarrist Noah Thomas. Was als Soloprojekt von Sace begann, wurde 2024 ein Duo: weicher, melodischer Gesang und Pop-Hooks über schweren Gitarren.', array['Das erste Album, brutalist, erschien im Mai 2026 bei Sumerian Records.', 'Alles, was sie zeigen, ist schwarz-weiß, mit Absicht.']::text[], 'https://en.wikipedia.org/wiki/Sace6'),
  ('dayseeker-creature-in-the-black-night-tour-19d5d1ef', 'tr', 'Dayseeker', 'post-hardcore · orange county', 'Orange County, Kaliforniya''dan post-hardcore, 2012''den beri: Rory Rodriguez vokal, Ramone Valerio bas, Zac Mayfield davul. Spinefarm''dan altı albüm; altıncısı Creature in the Black Night turneye adını veriyor.', array['Creature in the Black Night 24 Ekim 2025''te çıktı.', 'Metalcore ile post-hardcore arasında bir yerde.']::text[], 'https://en.wikipedia.org/wiki/Dayseeker'),
  ('dayseeker-creature-in-the-black-night-tour-19d5d1ef', 'en', 'Dayseeker', 'post-hardcore · orange county', 'Post-hardcore from Orange County, California, since 2012: Rory Rodriguez sings, Ramone Valerio plays bass, Zac Mayfield drums. Six albums on Spinefarm; the sixth, Creature in the Black Night, is the one this tour is named after.', array['Creature in the Black Night came out on 24 October 2025.', 'Somewhere between metalcore and post-hardcore.']::text[], 'https://en.wikipedia.org/wiki/Dayseeker'),
  ('dayseeker-creature-in-the-black-night-tour-19d5d1ef', 'de', 'Dayseeker', 'post-hardcore · orange county', 'Post-Hardcore aus Orange County, Kalifornien, seit 2012: Rory Rodriguez singt, Ramone Valerio spielt Bass, Zac Mayfield Schlagzeug. Sechs Alben bei Spinefarm; das sechste, Creature in the Black Night, gibt der Tour den Namen.', array['Creature in the Black Night erschien am 24. Oktober 2025.', 'Irgendwo zwischen Metalcore und Post-Hardcore.']::text[], 'https://de.wikipedia.org/wiki/Dayseeker'),
  ('ariana-baborie-toll-die-energie-a110c140', 'tr', 'Ariana Baborie', 'podcastçi ve sunucu · berlin', 'Berlinli radyo ve televizyon sunucusu, podcastçi ve yazar, 1988 doğumlu; Almanca ve Farsça ile iki dilli büyüdü. Önce radyo, sonra NightWash ve Quatsch Comedy Club''ta stand-up.', array['Laura Larsson ile Herrengedeck podcastini yaptı (2016–2021); 2020''de Alman Komedi Ödülü''nü aldılar.', '2018''de Sat.1''deki Dinner Party gece programını Oliver Pocher ile dönüşümlü sundu.']::text[], 'https://de.wikipedia.org/wiki/Ariana_Baborie'),
  ('ariana-baborie-toll-die-energie-a110c140', 'en', 'Ariana Baborie', 'podcaster and presenter · berlin', 'Radio and TV presenter, podcaster and author from Berlin, born 1988; she grew up speaking German and Persian. Started on radio, then stand-up at NightWash and the Quatsch Comedy Club.', array['With Laura Larsson she hosted the podcast Herrengedeck (2016 to 2021), which won the German Comedy Award in 2020.', 'In 2018 she hosted the late-night show Dinner Party on Sat.1, alternating with Oliver Pocher.']::text[], 'https://de.wikipedia.org/wiki/Ariana_Baborie'),
  ('ariana-baborie-toll-die-energie-a110c140', 'de', 'Ariana Baborie', 'podcasterin und moderatorin · berlin', 'Radio- und Fernsehmoderatorin, Podcasterin und Autorin aus Berlin, Jahrgang 1988; zweisprachig mit Deutsch und Persisch aufgewachsen. Erst Radio, dann Comedy bei NightWash und im Quatsch Comedy Club.', array['Mit Laura Larsson hostete sie den Podcast Herrengedeck (2016 bis 2021), 2020 mit dem Deutschen Comedypreis ausgezeichnet.', '2018 moderierte sie im Wechsel mit Oliver Pocher die Late-Night-Show Dinner Party auf Sat.1.']::text[], 'https://de.wikipedia.org/wiki/Ariana_Baborie'),
  ('bell-book-and-candle-club-tour-exclusive-15092b38', 'tr', 'Bell Book & Candle', 'pop grubu · 1994, berlin', 'Berlinli pop grubu; 1994''te Doğu Alman grubu Rosalili''de birlikte çalmış Jana Groß, Andy Birr ve Hendrik Röder kurdu. İlk single''ları Rescue Me (1997) Almanya, Avusturya ve İsviçre''de ilk üçe girdi.', array['Rescue Me Almanya ve Avusturya''da platin oldu.', 'Whitney Houston ve Roxette''in Almanya turnelerinde açılış yaptılar.']::text[], 'https://de.wikipedia.org/wiki/Bell_Book_%26_Candle'),
  ('bell-book-and-candle-club-tour-exclusive-15092b38', 'en', 'Bell Book & Candle', 'pop band · 1994, berlin', 'Berlin pop band founded in 1994 by Jana Groß, Andy Birr and Hendrik Röder, who had played together in the East German band Rosalili. Their first single, Rescue Me (1997), reached the top three in Germany, Austria and Switzerland.', array['Rescue Me went platinum in Germany and Austria.', 'They opened the German tours of Whitney Houston and Roxette.']::text[], 'https://de.wikipedia.org/wiki/Bell_Book_%26_Candle'),
  ('bell-book-and-candle-club-tour-exclusive-15092b38', 'de', 'Bell Book & Candle', 'popband · 1994, berlin', 'Berliner Popband, 1994 von Jana Groß, Andy Birr und Hendrik Röder gegründet, die schon in der DDR-Band Rosalili zusammen spielten. Die erste Single Rescue Me (1997) kam in Deutschland, Österreich und der Schweiz in die Top 3.', array['Rescue Me bekam Platin in Deutschland und Österreich.', 'Sie spielten im Vorprogramm der Deutschland-Tourneen von Whitney Houston und Roxette.']::text[], 'https://de.wikipedia.org/wiki/Bell_Book_%26_Candle'),
  ('tarmo-peltokoski-and-hong-kong-philharmonic-orch-9b0779bd', 'tr', 'Tarmo Peltokoski & Hong Kong Philharmonic', 'şef · 2000, vaasa · orkestra · 1947, hong kong', 'Tarmo Peltokoski Finlandiyalı şef, piyanist ve besteci; 2000''de Vaasa''da doğdu, 14 yaşından itibaren Jorma Panula''nın özel öğrencisiydi. Hong Kong Filarmoni 1947''de amatör bir orkestra olarak başladı, 1974''te profesyonel oldu.', array['21 yaşında Deutsche Kammerphilharmonie Bremen onu tarihindeki ilk baş konuk şef yaptı.', 'Orkestranın adı 1957''ye kadar Sino-British Orchestra''ydı.']::text[], 'https://en.wikipedia.org/wiki/Tarmo_Peltokoski'),
  ('tarmo-peltokoski-and-hong-kong-philharmonic-orch-9b0779bd', 'en', 'Tarmo Peltokoski & Hong Kong Philharmonic', 'conductor · 2000, vaasa · orchestra · 1947, hong kong', 'Tarmo Peltokoski is a Finnish conductor, pianist and composer, born in 2000 in Vaasa; a private student of Jorma Panula from the age of 14. The Hong Kong Philharmonic started in 1947 as an amateur orchestra and turned professional in 1974.', array['At 21 the Deutsche Kammerphilharmonie Bremen made him its first ever principal guest conductor.', 'The orchestra was called the Sino-British Orchestra until 1957.']::text[], 'https://en.wikipedia.org/wiki/Tarmo_Peltokoski'),
  ('tarmo-peltokoski-and-hong-kong-philharmonic-orch-9b0779bd', 'de', 'Tarmo Peltokoski & Hong Kong Philharmonic', 'dirigent · 2000, vaasa · orchester · 1947, hongkong', 'Tarmo Peltokoski ist ein finnischer Dirigent, Pianist und Komponist, 2000 in Vaasa geboren; ab 14 Privatschüler von Jorma Panula. Das Hong Kong Philharmonic begann 1947 als Laienorchester und wurde 1974 professionell.', array['Mit 21 machte ihn die Deutsche Kammerphilharmonie Bremen zu ihrem ersten Ersten Gastdirigenten überhaupt.', 'Bis 1957 hieß das Orchester Sino-British Orchestra.']::text[], 'https://en.wikipedia.org/wiki/Tarmo_Peltokoski'),
  ('son-mieux-24-hours-eu-album-tour-05c6159c', 'tr', 'Son Mieux', 'indie pop · lahey', 'Lahey''den indie pop, Camiel Meiresonne''un etrafında. 2015''te solo projesi olarak başladı, sonra elektronik sesli bir gruba dönüştü; ilk albüm Faire de Son Mieux (2019) Hollanda listesine 16''dan girdi.', array['İlk single''ları Easy''den sonra 2015''te 3FM Serious Talent seçildiler.', 'Multicolor (2022) single''ı geniş kitleye açılışları oldu.']::text[], 'https://en.wikipedia.org/wiki/Son_Mieux'),
  ('son-mieux-24-hours-eu-album-tour-05c6159c', 'en', 'Son Mieux', 'indie pop · the hague', 'Indie pop from The Hague around Camiel Meiresonne. It began as his solo project in 2015, then grew into a band with electronics; the first album, Faire de Son Mieux (2019), entered the Dutch charts at 16.', array['Named 3FM Serious Talent in 2015 after their first single, Easy.', 'The single Multicolor (2022) was their breakthrough with the wider public.']::text[], 'https://en.wikipedia.org/wiki/Son_Mieux'),
  ('son-mieux-24-hours-eu-album-tour-05c6159c', 'de', 'Son Mieux', 'indie-pop · den haag', 'Indie-Pop aus Den Haag um Camiel Meiresonne. 2015 als sein Soloprojekt begonnen, dann eine Band mit Elektronik; das erste Album Faire de Son Mieux (2019) stieg auf Platz 16 der niederländischen Charts ein.', array['2015 nach der ersten Single Easy zum 3FM Serious Talent ernannt.', 'Die Single Multicolor (2022) war der Durchbruch beim großen Publikum.']::text[], 'https://en.wikipedia.org/wiki/Son_Mieux'),
  ('chloe-slater-riot-youth-tour-598a73ef', 'tr', 'Chloe Slater', 'şarkıcı ve söz yazarı · manchester', 'İngiliz şarkıcı ve söz yazarı, 2003 doğumlu; Bournemouth''ta annesiyle büyüdü, Manchester''da yaşıyor. Toplum ve siyaset üzerine yazıyor; ikinci single''ı 24 Hours, influencer kültürüne bir eleştiri, TikTok''ta viral oldu.', array['Şimdiye kadar iki EP: You Can''t Put a Price on Fun (2024) ve Love Me Please (2025).', 'İlk albümü Riot Youth 9 Ekim 2026''da çıktı ve turneye adını veriyor.']::text[], 'https://en.wikipedia.org/wiki/Chloe_Slater'),
  ('chloe-slater-riot-youth-tour-598a73ef', 'en', 'Chloe Slater', 'singer-songwriter · manchester', 'English singer-songwriter, born 2003, raised by her mother in Bournemouth, based in Manchester. She writes about social and political things; her second single, 24 Hours, a takedown of influencer culture, went viral on TikTok.', array['Two EPs so far: You Can''t Put a Price on Fun (2024) and Love Me Please (2025).', 'Her first album, Riot Youth, came out on 9 October 2026 and gives this tour its name.']::text[], 'https://en.wikipedia.org/wiki/Chloe_Slater'),
  ('chloe-slater-riot-youth-tour-598a73ef', 'de', 'Chloe Slater', 'singer-songwriterin · manchester', 'Englische Singer-Songwriterin, Jahrgang 2003, bei ihrer Mutter in Bournemouth aufgewachsen, in Manchester zu Hause. Sie schreibt über Gesellschaft und Politik; ihre zweite Single 24 Hours, eine Abrechnung mit der Influencer-Kultur, ging auf TikTok viral.', array['Bisher zwei EPs: You Can''t Put a Price on Fun (2024) und Love Me Please (2025).', 'Ihr erstes Album Riot Youth erschien am 9. Oktober 2026 und gibt der Tour den Namen.']::text[], 'https://en.wikipedia.org/wiki/Chloe_Slater'),
  ('nimo-home-sweet-home-arena-tour-2026-74fd3bf2', 'tr', 'Nimo', 'rapçi · karlsruhe', 'İran kökenli Alman rapçi; 1995''te Karlsruhe''de Nima Yaghobi adıyla doğdu. Yıllarca Frankfurt''taki 385idéal etiketindeydi; 2020''de Tamim Amiri ile kendi şirketi Moonboys Entertainment''ı kurdu.', array['25 Aralık 1995 doğumlu.', '385idéal, Universal ile ortak çalışıyordu.']::text[], 'https://de.wikipedia.org/wiki/Nimo_(Rapper)'),
  ('nimo-home-sweet-home-arena-tour-2026-74fd3bf2', 'en', 'Nimo', 'rapper · karlsruhe', 'German rapper of Iranian descent, born Nima Yaghobi in Karlsruhe in 1995. For years with the Frankfurt label 385idéal; in 2020 he started his own, Moonboys Entertainment, with Tamim Amiri.', array['Born on 25 December 1995.', '385idéal worked together with the major label Universal.']::text[], 'https://de.wikipedia.org/wiki/Nimo_(Rapper)'),
  ('nimo-home-sweet-home-arena-tour-2026-74fd3bf2', 'de', 'Nimo', 'rapper · karlsruhe', 'Deutscher Rapper iranischer Abstammung, 1995 als Nima Yaghobi in Karlsruhe geboren. Jahrelang beim Frankfurter Label 385idéal; 2020 gründete er mit Tamim Amiri sein eigenes, Moonboys Entertainment.', array['Geboren am 25. Dezember 1995.', '385idéal arbeitete mit dem Major-Label Universal zusammen.']::text[], 'https://de.wikipedia.org/wiki/Nimo_(Rapper)'),
  ('undeath-d46b134a', 'tr', 'Undeath', 'death metal · rochester, new york', 'Rochester, New York''tan eski usul death metal, 2018''den beri. Prosthetic Records''tan üç albüm: Lesions of a Different Kind (2020), It''s Time... to Rise from the Grave (2022) ve More Insane (2024).', array['Cannibal Corpse ile karşılaştırılıyorlar.', 'Sahne tavırlarına "parti death metal" dendi.']::text[], 'https://en.wikipedia.org/wiki/Undeath_(band)'),
  ('undeath-d46b134a', 'en', 'Undeath', 'death metal · rochester, new york', 'Old-school death metal from Rochester, New York, since 2018. Three albums on Prosthetic Records: Lesions of a Different Kind (2020), It''s Time... to Rise from the Grave (2022) and More Insane (2024).', array['They get compared to Cannibal Corpse.', 'Their stage attitude has been called "party death metal".']::text[], 'https://en.wikipedia.org/wiki/Undeath_(band)'),
  ('undeath-d46b134a', 'de', 'Undeath', 'death metal · rochester, new york', 'Old-School-Death-Metal aus Rochester, New York, seit 2018. Drei Alben bei Prosthetic Records: Lesions of a Different Kind (2020), It''s Time... to Rise from the Grave (2022) und More Insane (2024).', array['Man vergleicht sie mit Cannibal Corpse.', 'Ihre Bühnenhaltung wurde „Party-Death-Metal“ genannt.']::text[], 'https://en.wikipedia.org/wiki/Undeath_(band)')
) as v(slug, lang, name, kicker, who, facts, source_url)
join public.events e on e.slug = v.slug
on conflict (event_id, lang) do update
  set name = excluded.name, kicker = excluded.kicker, who = excluded.who, facts = excluded.facts,
      source_url = excluded.source_url, made_at = now();
